'use strict';
let motionRecordArmed=false,motionTake=null,motionRecordRAF=0;
document.querySelector('.studio-toolbar').insertAdjacentHTML('afterbegin','<button id="openMotionRecording">Record movement</button>');
document.body.insertAdjacentHTML('beforeend','<dialog id="motionRecordingDialog"><div class="tool-heading"><h2>Record a performance</h2><button id="closeMotionRecording">Close</button></div><p class="note">Select a character, set the playhead, then arm recording. Drag the character to record movement, or drag one hand/foot joint to record its pose. Release to finish. Esc cancels. Your take becomes ordinary editable keyframes.</p><label>Record<select id="motionRecordingMode"><option value="position">Character movement</option><option value="joint">Hand / foot / head pose</option></select></label><label>Maximum take (s)<input id="motionRecordingLength" type="number" min="0.2" max="30" value="5" step="0.1"></label><label>Samples per second<select id="motionRecordingFPS"><option>15</option><option>30</option></select></label><label>Mouse smoothing<input id="motionRecordingSmooth" type="range" min="0" max="90" value="35"></label><button id="armMotionRecording" class="primary">Arm recording</button></dialog><div id="motionTakeStatus" hidden><span></span><button id="finishMotionTake">Finish</button><button id="cancelMotionTake">Cancel</button></div>');
$('openMotionRecording').onclick=()=>{const o=object();if(!isAnimatedCharacter(o)||o.locked)return toast('Select an unlocked character or picture rig.');stop();$('motionRecordingDialog').showModal()};$('closeMotionRecording').onclick=()=>$('motionRecordingDialog').close();$('armMotionRecording').onclick=()=>{const o=object();if(!isAnimatedCharacter(o)||o.locked)return;motionRecordArmed=true;canvasMode=$('motionRecordingMode').value==='joint'?'pose':'select';$('motionRecordingDialog').close();$('hint').textContent='Recording armed · drag '+(canvasMode==='pose'?'a joint handle':'your character')+' · Esc cancels';$('stage').style.cursor='crosshair';draw()};
function beginMotionTake(e){const o=object();if(!isAnimatedCharacter(o)||o.locked)return;const p=pointerWorld(e),mode=$('motionRecordingMode').value,handle=mode==='joint'?poseHandles(o).find(h=>Math.hypot(h.x-p.x,h.y-p.y)<16/cameraAt(current(),time).zoom):null;if(mode==='joint'&&!handle)return toast('Drag a joint handle to begin the take.');if(mode==='position'&&!hitLayer(o,p))return toast('Drag the selected character to begin.');const length=Math.min(+$('motionRecordingLength').value||5,clipEnd(o)-time);if(length<.1)return toast('Move the playhead earlier in the character clip.');stop();const before=structuredClone(o),initial=stateAt(o,time);motionTake={o,before,sceneId:current().id,start:time,length,mode,key:handle?.key,initial,base:rawStateAt(o,time),camera:cameraAt(current(),time),pointer:p,last:p,smoothed:p,started:performance.now(),fps:+$('motionRecordingFPS').value,samples:[],lastFrame:-1};motionRecordArmed=false;window.editorTaskBusy=true;window.motionRecordingBusy=true;o.characterLoop='none';if(mode==='position'&&o.motionPath)o.motionPath.enabled=false;o.actionBlocks=(o.actionBlocks||[]).filter(b=>b.start+b.duration<time||b.start>time+length||mode==='position'&&b.type!=='walk');if(mode==='joint'){o.lookTargetId=null;o.pointTargetId=null;if(o.type==='puppet')o.ikEnabled=true}o.keys=o.keys.filter(k=>k.t<time-.001||k.t>time+length+.001);$('stage').setPointerCapture(e.pointerId);$('motionTakeStatus').hidden=false;recordMotionFrame(performance.now())}
function recordMotionFrame(now){const take=motionTake;if(!take)return;if(current().id!==take.sceneId)return finishMotionRecording(true);const elapsed=Math.min(take.length,(now-take.started)/1000),frame=Math.floor(elapsed*take.fps);time=take.start+elapsed;if(frame!==take.lastFrame){take.lastFrame=frame;const amount=1-+$('motionRecordingSmooth').value/100;take.smoothed={x:take.smoothed.x+(take.last.x-take.smoothed.x)*amount,y:take.smoothed.y+(take.last.y-take.smoothed.y)*amount};const at=Math.min(take.start+take.length,take.start+frame/take.fps);let v;if(take.mode==='position')v={...take.base,x:take.initial.x+take.smoothed.x-take.pointer.x,y:take.initial.y+take.smoothed.y-take.pointer.y};else{poseJoint(take.o,take.key,take.smoothed,take.initial,take.base);v=structuredClone(take.o.keys.find(k=>Math.abs(k.t-time)<.015)?.v||rawStateAt(take.o,time));take.o.keys=take.o.keys.filter(k=>Math.abs(k.t-time)>=.015)}writePoseKey(take.o,v,at);take.samples.push({t:at,v:{...v}})}draw();$('motionTakeStatus').querySelector('span').textContent='● Recording '+elapsed.toFixed(1)+' / '+take.length.toFixed(1)+' s';if(elapsed>=take.length)return finishMotionRecording();motionRecordRAF=requestAnimationFrame(recordMotionFrame)}
function finishMotionRecording(cancel=false){motionRecordArmed=false;$('stage').style.cursor='';cancelAnimationFrame(motionRecordRAF);const take=motionTake;window.motionRecordingBusy=false;window.editorTaskBusy=false;$('motionTakeStatus').hidden=true;if(!take)return render();if(!cancel){const endTime=Math.min(take.start+take.length,take.start+(performance.now()-take.started)/1000);if(endTime-(take.samples.at(-1)?.t??take.start)>.02){time=endTime;const amount=1-+$('motionRecordingSmooth').value/100;take.smoothed={x:take.smoothed.x+(take.last.x-take.smoothed.x)*amount,y:take.smoothed.y+(take.last.y-take.smoothed.y)*amount};let v;if(take.mode==='position')v={...take.base,x:take.initial.x+take.smoothed.x-take.pointer.x,y:take.initial.y+take.smoothed.y-take.pointer.y};else{poseJoint(take.o,take.key,take.smoothed,take.initial,take.base);v=structuredClone(take.o.keys.find(k=>Math.abs(k.t-time)<.015)?.v||rawStateAt(take.o,time))}take.samples.push({t:endTime,v})}}motionTake=null;if(cancel||take.samples.length<2){for(const key of Object.keys(take.o))delete take.o[key];Object.assign(take.o,take.before);time=take.start;render();return toast('Recording canceled.')}const end=take.samples.at(-1).t;take.o.keys=[...take.before.keys.filter(k=>k.t<take.start-.015||k.t>end+.015),...take.samples].sort((a,b)=>a.t-b.t);take.o.ease='linear';// Recorded points should preserve the performed timing.
 if(take.before.actionBlocks){const affected=take.before.actionBlocks.filter(b=>!(take.o.actionBlocks||[]).some(a=>a.id===b.id));for(const b of affected)if(b.start>=end+.015)take.o.actionBlocks.push(b)}if(typeof finishBodyRecording==='function')finishBodyRecording(take,end);time=end;save();render();toast('Performance recorded as '+take.samples.length+' editable keyframes.')}
const recordDown=$('stage').onpointerdown,recordMove=$('stage').onpointermove,recordUp=$('stage').onpointerup,recordCancel=$('stage').onpointercancel;
$('stage').onpointerdown=e=>{if(motionRecordArmed){if(e.button===0){e.preventDefault();beginMotionTake(e)}return}return recordDown(e)};$('stage').onpointermove=e=>{if(motionTake){motionTake.last=pointerWorld(e,{camera:motionTake.camera});return}return recordMove(e)};$('stage').onpointerup=()=>motionTake?finishMotionRecording():recordUp();$('stage').onpointercancel=()=>motionTake?finishMotionRecording(true):recordCancel();$('finishMotionTake').onclick=()=>finishMotionRecording();$('cancelMotionTake').onclick=()=>finishMotionRecording(true);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(motionTake||motionRecordArmed)){e.preventDefault();finishMotionRecording(true)}});
const recordExtras=renderExtras;renderExtras=function(){recordExtras();if(motionRecordArmed)$('hint').textContent='Recording armed · drag to perform · Esc cancels'};
document.addEventListener('pointerdown',e=>{if(motionTake&&e.target!==$('stage')&&!e.target.closest('#motionTakeStatus')){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('keydown',e=>{if(!motionTake)return;e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape')finishMotionRecording(true)},true);
